		43647, 43648, 43649, 43650, 43651, 43652, // Elk kelp
		43653, 43654, 43655, // Dark lace
		43656, 43657, 43658, // Elk kelp
		43659, 43660, 43661, 43662, 43663, 43664, 43665, 43666, 43667, 43668, 43669,
		43670, 43671, 43672, 43673, 43674,
