		43678, 43679, 43680, 43681, 43682, 43683, 43684, 43685, 43686, 43687, 43688,
		43690, 43691, 43694,
		43692, 43693, // Portal (decorative frames; the functional mine portal is 43730)
		43698, 43699, // Statue
